#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

// Assuming the following types/macros are defined as per the codebase
typedef int (*config_fn_t)(const char *, void *);

static int load_config_file(const char *filename, config_fn_t fn, void *data) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        return 0;
    }

    char line[1024];
    int count = 0;
    while (fgets(line, sizeof(line), file)) {
        // Remove trailing newline
        line[strcspn(line, "\n")] = '\0';
        if (fn(line, data)) {
            count++;
        }
    }

    fclose(file);
    return count;
}

int load_performance_config(config_fn_t fn, void *data) {
    int total = 0;

    // Check for exclusive configuration file
    if (config_exclusive_filename && *config_exclusive_filename) {
        total += load_config_file(config_exclusive_filename, fn, data);
    }

    // Check for system-wide configuration file
    const char *system_config = "/etc/performance.conf";
    total += load_config_file(system_config, fn, data);

    // Check for user-specific configuration file
    char *home = getenv("HOME");
    if (home) {
        char user_config[1024];
        snprintf(user_config, sizeof(user_config), "%s/.performance.conf", home);
        total += load_config_file(user_config, fn, data);
    }

    return total ? total : -1;
}
